-- Arbeitsrecht Berufsbildung > Berufsbildungsgesetz (BBiG) > Prüfungsanforderungen
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker eine Abschlussprüfung ablegen, um die Ausbildung abzuschließen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 37 BBiG schreibt die Abschlussprüfung vor"}, {"text": "Nein", "correct": false, "because": "Prüfung ist verpflichtend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb die Prüfungsanforderungen für einen Fachinformatiker selbst festlegen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 37 BBiG legt die Prüfungsanforderungen über die IHK fest"}, {"text": "Ja", "correct": false, "because": "IHK ist zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker die Zwischenprüfung wiederholen, wenn er sie nicht besteht?', 2, '[{"text": "Nein", "correct": true, "because": "§ 38 BBiG sieht keine Wiederholung der Zwischenprüfung vor"}, {"text": "Ja", "correct": false, "because": "Zwischenprüfung ist nicht wiederholbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Abschlussprüfung eines Fachinformatikers sowohl schriftliche als auch praktische Teile umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 37 BBiG und die Prüfungsordnung fordern beides"}, {"text": "Nein", "correct": false, "because": "Beide Teile sind vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker die Abschlussprüfung vorzeitig ablegen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 45 BBiG erlaubt dies bei entsprechender Leistung"}, {"text": "Nein", "correct": false, "because": "Vorzeitige Prüfung ist möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Paragraph des BBiG regelt die Abschlussprüfung eines Fachinformatikers?', 2, '[{"text": "§ 37 BBiG", "correct": true, "because": "Legt die Abschlussprüfung fest"}, {"text": "§ 15 BBiG", "correct": false, "because": "Bezieht sich auf Berufsschule"}, {"text": "§ 22 BBiG", "correct": false, "because": "Regelt Kündigungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist für die Organisation der Abschlussprüfung eines Fachinformatikers verantwortlich?', 2, '[{"text": "Die zuständige Industrie- und Handelskammer (IHK)", "correct": true, "because": "§ 37 BBiG überträgt dies der IHK"}, {"text": "Der Ausbildungsbetrieb", "correct": false, "because": "Betrieb hat keine Prüfungsorganisation"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule ist nicht zuständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker die Abschlussprüfung nicht besteht?', 3, '[{"text": "Er kann sie zweimal wiederholen", "correct": true, "because": "§ 37 Abs. 2 BBiG erlaubt zwei Wiederholungen"}, {"text": "Die Ausbildung endet automatisch", "correct": false, "because": "Wiederholung möglich"}, {"text": "Er muss die gesamte Ausbildung wiederholen", "correct": false, "because": "Nur Prüfung wird wiederholt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prüfung ist für einen Fachinformatiker während der Ausbildung vorgeschrieben?', 3, '[{"text": "Zwischenprüfung", "correct": true, "because": "§ 38 BBiG schreibt sie vor"}, {"text": "Nur Abschlussprüfung", "correct": false, "because": "Zwischenprüfung ist zusätzlich"}, {"text": "Freiwillige Zertifizierungen", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer entscheidet über eine vorzeitige Zulassung zur Abschlussprüfung eines Fachinformatikers?', 3, '[{"text": "Die IHK", "correct": true, "because": "§ 45 BBiG überträgt dies der zuständigen Stelle"}, {"text": "Der Betrieb allein", "correct": false, "because": "IHK-Genehmigung erforderlich"}, {"text": "Der Auszubildende", "correct": false, "because": "Keine Eigenentscheidung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prüfungen muss ein Fachinformatiker gemäß BBiG ablegen?', 4, '[{"text": "Zwischenprüfung", "correct": true, "because": "§ 38 BBiG schreibt sie vor"}, {"text": "Abschlussprüfung", "correct": true, "because": "§ 37 BBiG fordert sie"}, {"text": "Private Zertifizierungen", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Berufsschulprüfungen", "correct": true, "because": "Teil der Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen muss ein Fachinformatiker für die Abschlussprüfung erfüllen?', 3, '[{"text": "Abschluss der Ausbildungszeit", "correct": true, "because": "§ 37 BBiG setzt dies voraus"}, {"text": "Mindestens 2 Jahre Berufserfahrung", "correct": false, "because": "Nicht erforderlich"}, {"text": "Teilnahme an der Zwischenprüfung", "correct": true, "because": "Voraussetzung für Abschluss"}, {"text": "Bestehen der Zwischenprüfung", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt für die Wiederholung der Abschlussprüfung eines Fachinformatikers?', 4, '[{"text": "Maximal zwei Wiederholungen", "correct": true, "because": "§ 37 Abs. 2 BBiG legt dies fest"}, {"text": "Kosten trägt der Auszubildende", "correct": false, "because": "Betrieb trägt Kosten"}, {"text": "Möglich bei Nichtbestehen", "correct": true, "because": "§ 37 Abs. 2 BBiG erlaubt dies"}, {"text": "Anmeldung durch die IHK", "correct": true, "because": "IHK organisiert die Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen hat das Nichtbestehen der Zwischenprüfung eines Fachinformatikers?', 3, '[{"text": "Keine direkte Auswirkung auf die Abschlussprüfung", "correct": true, "because": "§ 38 BBiG sieht dies vor"}, {"text": "Automatische Kündigung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hinweis für den Betrieb zur Förderung", "correct": true, "because": "Zweck der Zwischenprüfung"}, {"text": "Verlängerung der Ausbildungszeit", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen gelten für eine vorzeitige Abschlussprüfung eines Fachinformatikers?', 3, '[{"text": "Einvernehmen von Betrieb und Auszubildendem", "correct": true, "because": "§ 45 BBiG verlangt Zustimmung"}, {"text": "Hervorragende Leistungen", "correct": true, "because": "Begründung für Vorzeit"}, {"text": "Mindestens 3 Jahre Ausbildung", "correct": false, "because": "Nicht erforderlich"}, {"text": "Genehmigung durch die IHK", "correct": true, "because": "§ 45 BBiG fordert dies"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Fachinformatiker muss eine Abschlussprüfung ablegen. b) Die Zwischenprüfung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abschlussprüfung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Abschlussprüfung eines Fachinformatikers umfasst praktische Teile. b) Die IHK organisiert die Prüfungen.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 37 BBiG und IHK-Zuständigkeit"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker kann die Abschlussprüfung vorzeitig ablegen. b) Die Zwischenprüfung muss bestanden werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vorzeit möglich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Abschlussprüfung kann zweimal wiederholt werden. b) Der Betrieb legt die Prüfungsanforderungen fest.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wiederholung erlaubt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die IHK entscheidet über vorzeitige Prüfungen eines Fachinformatikers. b) Die Zwischenprüfung hat keinen Einfluss auf die Abschlussprüfung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 45 und § 38 BBiG bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

